import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        String[] arrayBuah = new String[3];
        arrayBuah[0] = "Apel";
        System.out.println(arrayBuah.length);

        List<String> listBuah = new ArrayList<>();
        listBuah.add("Apel");
        System.out.println(listBuah.size());

        listBuah.add("Jeruk");
        listBuah.add("Mangga");
        listBuah.add("Pisang");
        System.out.println(listBuah.size());
        System.out.println(listBuah);
    }
}

